<style>
.master-grid{display:grid;grid-template-columns:minmax(310px,430px) minmax(620px,1fr);gap:22px;align-items:start}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.form-grid .wide{grid-column:1/-1}.form-grid label{display:grid;gap:6px;font-size:13px;font-weight:750}.form-grid input,.form-grid select,.form-grid textarea{width:100%;padding:10px;border:1px solid var(--line);border-radius:7px;background:#fff}.status{margin-bottom:18px;padding:14px;border-left:4px solid var(--turquoise-dark);background:#e8fbfa}.protected{padding:11px;border-radius:8px;background:#fff6e4;color:#735315;font-size:13px}.record{margin-bottom:10px;border:1px solid var(--line);border-radius:10px;background:#fff}.record summary{padding:15px;cursor:pointer;font-weight:800}.record form{padding:0 15px 15px}.record-meta{font-size:13px;color:var(--muted);font-weight:500}.badge{display:inline-block;padding:3px 8px;border-radius:99px;background:#e1f7ed;color:#16724a;font-size:12px}.badge.off{background:#f6e7e7;color:#983d3d}.empty{padding:24px;color:var(--muted)}@media(max-width:1050px){.master-grid{grid-template-columns:1fr}}@media(max-width:650px){.form-grid{grid-template-columns:1fr}.form-grid .wide{grid-column:auto}}
</style>
